import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  random,
} from '../remotionShim';
import { evolvePath } from "@remotion/paths";
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Inter');

// Initialize font for standard number/label fallback styling if needed (clean san-serif)
const { fontFamily } = loadFont();

// Single Named Zod Schema matching requirements


export type ComponentNameProps = Record<string, any>;

const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#001b44",
  transparentBackground = false,
  durationInSeconds = 8,
  lineColor = "#ffffff",
  glowColor = "#3fa5ff",
  barFillColor = "#1d5eb8",
  floatingSymbolColor = "#0f428a",
  symbolCount = 15,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Generate deterministic floating dollar signs properties
  const floatingSymbols = useMemo(() => {
    return Array.from({ length: symbolCount }).map((_, i) => {
      const seed = i * 1000;
      const initialX = random(seed) * width;
      // Start below or at various heights
      const startY = height * 1.2 - random(seed + 1) * (height * 0.4);
      const speed = 1.5 + random(seed + 2) * 2.5;
      const scale = 0.5 + random(seed + 3) * 1.5;
      const opacity = 0.05 + random(seed + 4) * 0.25;
      const rotateSpeed = -1 + random(seed + 5) * 2;
      return { initialX, startY, speed, scale, opacity, rotateSpeed };
    });
  }, [symbolCount, width, height]);

  // Graph points mapping to 9:16 layout
  // We model a realistic, organic rising curve with intermediate steps like the reference image
  const points = useMemo(() => {
    const relativeCoords = [
      { x: 0.05, y: 0.82 },
      { x: 0.15, y: 0.77 },
      { x: 0.23, y: 0.81 },
      { x: 0.32, y: 0.73 },
      { x: 0.41, y: 0.75 },
      { x: 0.52, y: 0.65 },
      { x: 0.60, y: 0.69 },
      { x: 0.68, y: 0.57 },
      { x: 0.76, y: 0.62 },
      { x: 0.83, y: 0.48 },
      { x: 0.90, y: 0.35 },
    ];

    return relativeCoords.map((pt) => ({
      x: pt.x * width,
      y: pt.y * height,
    }));
  }, [width, height]);

  // Generate SVG Path for the Line
  const linePath = useMemo(() => {
    if (points.length === 0) return "";
    return points.reduce(
      (path, pt, i) => (i === 0 ? `M ${pt.x} ${pt.y}` : `${path} L ${pt.x} ${pt.y}`),
      ""
    );
  }, [points]);

  // Main graph animation progress
  const progressSpring = spring({
    frame,
    fps,
    config: {
      damping: 18,
      mass: 0.8,
      stiffness: 70,
    },
  });

  // Main evolution of the line based on spring logic
  const pathEvolution = evolvePath(progressSpring, linePath);

  // Generate individual column paths/coordinates to animate bar steps behind the line
  const barColumns = useMemo(() => {
    const colWidth = width / 18;
    // Sample Y values along the graph segments for dense background bars
    const barCount = 18;
    return Array.from({ length: barCount }).map((_, i) => {
      const x = width * 0.08 + (i / (barCount - 1)) * (width * 0.82);
      
      // Interpolate Y value based on closest graph segments
      let y = height * 0.85;
      for (let j = 0; j < points.length - 1; j++) {
        const p1 = points[j];
        const p2 = points[j + 1];
        if (x >= p1.x && x <= p2.x) {
          const ratio = (x - p1.x) / (p2.x - p1.x);
          y = p1.y + ratio * (p2.y - p1.y);
          break;
        }
      }
      return { x, targetY: y, width: colWidth };
    });
  }, [points, width, height]);

  // Determine the arrow head coordinates and angle
  const arrowMetrics = useMemo(() => {
    if (points.length < 2) return { x: 0, y: 0, angle: 0 };
    const lastPt = points[points.length - 1];
    const secondLastPt = points[points.length - 2];
    const dx = lastPt.x - secondLastPt.x;
    const dy = lastPt.y - secondLastPt.y;
    const angle = Math.atan2(dy, dx) * (180 / Math.PI);
    
    // We animate the position of the arrow along the path matching progressSpring
    const totalSegments = points.length - 1;
    const activeSegmentIndex = Math.min(
      Math.floor(progressSpring * totalSegments),
      totalSegments - 1
    );
    
    const segmentProgress = (progressSpring * totalSegments) % 1;
    const pStart = points[activeSegmentIndex];
    const pEnd = points[activeSegmentIndex + 1] || lastPt;
    
    const arrowX = pStart.x + (pEnd.x - pStart.x) * (segmentProgress || 1);
    const arrowY = pStart.y + (pEnd.y - pStart.y) * (segmentProgress || 1);

    return { x: arrowX, y: arrowY, angle };
  }, [points, progressSpring]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily,
        overflow: "hidden",
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Floating background dollar symbols */}
      {floatingSymbols.map((sym, index) => {
        const currentY = sym.startY - (frame * sym.speed);
        // Wrap-around logic to ensure continuous floating loops
        const relativeY = ((currentY + 200) % (height + 300)) - 100;
        const finalY = height + 100 - relativeY;
        const rotation = frame * sym.rotateSpeed;

        return (
          <div
            key={index}
            style={{
              position: "absolute",
              left: sym.initialX,
              top: finalY,
              fontSize: `${64 * sym.scale}px`,
              fontWeight: 800,
              color: floatingSymbolColor,
              opacity: sym.opacity,
              transform: `translate(-50%, -50%) rotate(${rotation}deg)`,
              userSelect: "none",
              pointerEvents: "none",
              zIndex: 1,
              transition: "none",
            }}
          >
            $
          </div>
        );
      })}

      {/* Main Graph Area */}
      <div
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          zIndex: 2,
          pointerEvents: "none",
        }}
      >
        <svg
          width={width}
          height={height}
          style={{ width: "100%", height: "100%", overflow: "visible" }}
        >
          <defs>
            {/* Smooth bar gradient mimicking the reference design */}
            <linearGradient id="barGradient" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={barFillColor} stopOpacity={0.8} />
              <stop offset="100%" stopColor={barFillColor} stopOpacity={0.02} />
            </linearGradient>
            
            {/* Glow filters for high-impact visual curve styling */}
            <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
              <feGaussianBlur stdDeviation="15" result="blur1" />
              <feGaussianBlur stdDeviation="30" result="blur2" />
              <feMerge>
                <feMergeNode in="blur2" />
                <feMergeNode in="blur1" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
          </defs>

          {/* Semi-transparent Vertical Grid Columns filling the graph up to the line height */}
          {barColumns.map((col, i) => {
            const barProgress = spring({
              frame: frame - i * 1.5,
              fps,
              config: { damping: 15 },
            });
            const currentBarY = interpolate(
              barProgress,
              [0, 1],
              [height, col.targetY],
              { extrapolateRight: "clamp" }
            );

            return (
              <rect
                key={i}
                x={col.x - col.width / 2}
                y={currentBarY}
                width={col.width * 0.85}
                height={Math.max(0, height - currentBarY)}
                fill="url(#barGradient)"
                rx={4}
                style={{ transition: "none" }}
              />
            );
          })}

          {/* Underlay glow path matching the main curve */}
          <path
            d={linePath}
            fill="none"
            stroke={glowColor}
            strokeWidth={16}
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeDasharray={pathEvolution.strokeDasharray}
            strokeDashoffset={pathEvolution.strokeDashoffset}
            opacity={0.65}
            filter="url(#glow)"
            style={{ transition: "none" }}
          />

          {/* Sharp core white/light blue rising line */}
          <path
            d={linePath}
            fill="none"
            stroke={lineColor}
            strokeWidth={8}
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeDasharray={pathEvolution.strokeDasharray}
            strokeDashoffset={pathEvolution.strokeDashoffset}
            style={{ transition: "none" }}
          />

          {/* Dynamic Floating Arrow Pointer on Path Head */}
          {progressSpring > 0.01 && (
            <g
              transform={`translate(${arrowMetrics.x}, ${arrowMetrics.y}) rotate(${arrowMetrics.angle})`}
              style={{ transition: "none" }}
            >
              {/* Outer arrowhead glow */}
              <path
                d="M -15 -18 L 22 0 L -15 18 L -6 0 Z"
                fill={lineColor}
                filter="url(#glow)"
                style={{ transition: "none" }}
              />
              <path
                d="M -15 -18 L 22 0 L -15 18 L -6 0 Z"
                fill={lineColor}
                style={{ transition: "none" }}
              />
            </g>
          )}
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default ComponentName;